    "summary": "最新天文学研究表明，超大质量黑洞产生的“黑洞风”可能正在吹散巨型星系中的气体，从而剥夺了这些星系未来形成新恒星所需的原料。",
    "body": "天文学家观测发现，巨型星系中心的超大质量黑洞在活跃期会释放出强大的物质外流，即“黑洞风”。这些高能风会加热或直接吹散星系内部的冷气体云。\n\n冷气体是孕育新恒星的必要原料。研究指出，黑洞风的强烈作用导致巨型星系内的气体大量流失，进而抑制甚至完全切断了新恒星的形成过程，使星系逐渐走向“衰老”。\n\n这一发现为理解星系演化机制提供了重要线索，有助于科学界解释为何宇宙中许多巨型椭圆星系在晚期会停止恒星形成活动。",
