    "summary": "一种名为“回波图”的新技术表明，超大质量黑洞周围可能存在暗物质团簇，为研究暗物质提供了新视角。",
    "body": "近日，天文学家提出了一种名为“回波图”（echo map）的新技术，用于研究超大质量黑洞周围的物理环境。研究表明，这些黑洞周围可能被暗物质团簇所包围。\n\n该技术通过分析黑洞吸积盘发出的光在周围物质中产生的“回波”延迟，能够间接探测到不可见的暗物质分布。这一发现不仅有助于理解超大质量黑洞的生长机制，也为暗物质的性质和分布提供了全新的观测手段。\n\n尽管暗物质尚未被直接探测到，但“回波图”技术为未来的天文观测和深空探测任务提供了重要的理论支持，推动了前沿天体物理学与空间科学的发展。",
    "category": "商业航天",
