    "title": "地球海洋从何而来？新研究指或由地球自身形成",
    "summary": "关于地球海洋起源的传统观点受到挑战，新研究认为地球上的水可能并非来自彗星撞击，而是由地球自身内部过程产生。",
    "body": "长期以来，科学界普遍认为地球上的海洋是由富含水分的小行星或彗星在地球形成后期撞击带来的。然而，近期的科学研究对这一传统观点提出了挑战，探讨了地球自身“制造”海洋的可能性。\n\n研究表明，地球在吸积形成过程中，其内部的岩浆洋和含水矿物可能储存了大量的水。随着地球的冷却和地质演化，这些深部的水通过火山活动和脱气作用被释放到地表，最终汇聚形成了广阔的海洋。\n\n这一假说不仅重塑了人类对地球水资源起源的认知，也对寻找系外宜居行星具有重要指导意义。如果行星能够通过内部机制自行产生海洋，那么宇宙中存在液态水和潜在生命的概率将大幅增加。",
