    "title": "何恺明团队新作：258M参数实现高质量文生图",
    "summary": "何恺明指导的全员本科生团队提出仅需2.58亿参数的文生图模型，大幅降低了文本生成图像的参数量与算力门槛。",
    "body": "近日，由何恺明指导的全员本科生团队发布了一项关于文本生成图像的新研究。该研究提出了一种仅需2.58亿（258M）参数的模型，即可实现高质量的图像生成效果。\n\n这一成果打破了当前文生图领域动辄需要数十亿甚至上百亿参数大模型的固有认知。通过大幅缩减模型参数量，该技术不仅显著降低了训练和推理的算力成本，还为文生图模型在边缘设备和端侧的本地化部署提供了新的技术路径。\n\n该研究展示了小参数模型在生成式AI领域的巨大潜力，有望推动AI图像生成技术向更高效、更轻量化的方向发展，进一步加速AIGC应用的普及与商业化落地。",
