    "body": "长期以来，开发者在进行带有请求体的只读查询时，由于GET方法不支持请求体，往往不得不借用POST方法，这违背了RESTful设计中POST用于创建资源的语义。\n\n为解决这一痛点，互联网工程任务组（IETF）正推进HTTP QUERY方法成为正式标准。该方法专门用于带有请求体的安全、幂等查询操作，使API语义更加清晰。\n\n这一标准的落地将极大改善Web API的设计规范，提升开发者体验，并为未来的Web框架、云原生网关及API管理中间件提供更标准、更高效的处理依据。",
