    "summary": "微星推出搭载英特尔最新Arc显卡与32GB内存的Claw 8 EX AI+掌机，定价1799美元，并暗示今年面临成本压力可能再次涨价。",
    "body": "微星（MSI）正式发布了新款 Claw 8 EX AI+ 游戏掌机。该设备搭载了英特尔最新的 Arc G3 Extreme 显卡以及 32GB 大容量内存，旨在提供更强劲的 AI 与游戏性能，其官方定价为 1799 美元。\n\n除了公布新硬件，微星还对当前的行业环境表达了担忧。公司表示今年将是“艰难的一年”，由于供应链和零部件成本的压力，未来不排除产品“再次涨价”的可能性。\n\n这一表态反映了当前消费电子及 PC 硬件市场面临的普遍成本挑战。随着 AI PC 和高性能掌机对先进制程芯片及大容量内存的需求增加，上游成本的波动正逐渐向终端产品定价传导。",
