    "body": "如果物理人工智能想要取得与大语言模型同等的成就，首先必须解决训练数据匮乏的难题。与数字世界的文本数据不同，收集机器人所需的物理交互数据往往是一项繁琐、辛苦且缺乏光环的“脏活累活”。\n\n面对这一数据瓶颈，部分AI实验室已经选择将这项繁重的工作外包。他们开始付费聘请XDOF等专业公司来代为收集高质量的机器人训练数据，以加速物理AI模型的研发与迭代进程。\n\n这一趋势表明，具身智能领域正在形成更细致的产业分工。通过专业化的数据采集服务，物理AI有望夯实底层数据基础，从而在现实世界中实现更广泛的落地与应用。",
